# JRC CEMS-GLOFAS flood-depth return-period layers (permanent water removed).
# Source: data/mapfiles/data/jrc_flood/jrc_flood_rp{10,20,50,75,100}_nowater_gha.tif
# Mounted into mapserver at /opt/rasterdata/jrc_flood/.

LAYER
    NAME "flood_extent_rp10"
    TYPE RASTER
    STATUS ON
    DATA "/opt/rasterdata/jrc_flood/jrc_flood_rp10_nowater_gha.tif"
    MASK "gha_admin_extent_mask"
    PROCESSING "NODATA=-9999"
    INCLUDE "shared/common-layer-properties.map"
    TYPE RASTER
    INCLUDE "classifications/flood-extent-jrc-depth.classes.map"
    METADATA
        "wms_title" "Flood Extent / Hazard - 10 Year Return Period"
        "wms_abstract" "JRC CEMS-GLOFAS flood-depth raster for a 1-in-10 year fluvial event (permanent water removed)"
        INCLUDE "shared/wms-layer-metadata.map"
    END
END

